contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tests putting funds into c and checking observable invariants
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read balance of this address in c before the Put
        // Acc is public so Acc(address) returns (unlockTime, balance) automatically
        (, uint beforeBal) = c.Acc(address(this));
        uint beforeContractEth = address(c).balance;

        // perform Put with given amount, capture whether it reverted
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        (, uint afterBal) = c.Acc(address(this));
        uint afterContractEth = address(c).balance;

        // If the call reverted then nothing should have changed; otherwise
        // the holder balance must have increased exactly by amount and
        // the contract's ether balance must also have increased by amount.
        assert(reverted
               ? (afterBal == beforeBal && afterContractEth == beforeContractEth)
               : (afterBal == beforeBal + amount && afterContractEth == beforeContractEth + amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to invoke Collect and assert that on success both on-chain balance and recorded balance decrease by amount
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this test contract can send putAmount to c
        require(address(this).balance >= putAmount);

        // initial observed stored balance for this contract in c
        (, uint beforeRecorded) = c.Acc(address(this));
        uint beforeContractEth = address(c).balance;

        // perform a Put to fund the holder mapping so Collect can succeed potentially
        bool putReverted;
        try c.Put{value: putAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // update observations after Put
        (, uint midRecorded) = c.Acc(address(this));
        uint midContractEth = address(c).balance;

        // Now attempt Collect; capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // observations after Collect
        (, uint afterRecorded) = c.Acc(address(this));
        uint afterContractEth = address(c).balance;

        // If Collect succeeded then both the contract's ETH balance and the recorded balance for this address
        // must have decreased by exactly collectAmount compared to just before Collect (i.e., compared to mid- values).
        // If Collect reverted then nothing observable must have changed by the Collect call (so after == mid).
        assert(
            collectReverted
            ? (afterRecorded == midRecorded && afterContractEth == midContractEth)
            : (midRecorded >= collectAmount && midRecorded - collectAmount == afterRecorded && midContractEth >= collectAmount && midContractEth - collectAmount == afterContractEth)
        );
    }

    // allow receiving ETH in case c sends Ether back to this contract during Collect
    receive() external payable { }
}

