contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: perform a Put to ensure some recorded balance and contract balance, then attempt Collect.
    // Parameters: unlockTime for Put, putAmount to send to Put, collectAmount to request from Collect.
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Observe contract Ether balance and recorded balance before any calls
        uint beforeEth = address(c).balance;
        (, uint beforeRecorded) = c.Acc(address(this));

        // Perform Put to deposit putAmount (may revert)
        bool putReverted;
        try c.Put{value: putAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe balances after Put and before Collect
        uint midEth = address(c).balance;
        (, uint midRecorded) = c.Acc(address(this));

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after Collect
        uint afterEth = address(c).balance;
        (, uint afterRecorded) = c.Acc(address(this));

        // If Collect succeeded then (1) contract Ether balance decreased by exactly collectAmount
        // and (2) the recorded balance decreased by at least collectAmount (cannot drop less than sent value).
        // If Collect reverted then no requirement. Also if Put reverted then mid values reflect no deposit,
        // but rule still must hold for all inputs.
        assert(collectReverted || (midEth - afterEth == collectAmount && midRecorded - afterRecorded >= collectAmount));
    }

    // allow receiving ETH from Collect
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We deposit some Ether via Put, then try Collect. We assert that if Collect did not revert,
    // then the contract balance did not increase and the recorded balance did not increase.
    // Parameters:
    //  putUnlock - unlock time passed to Put
    //  putAmount - amount of wei to send to Put
    //  collectAmount - amount requested in Collect
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // observe before
        uint beforeEth = address(c).balance;
        (, uint beforeRecorded) = c.Acc(address(this));

        // perform Put (may revert)
        bool putReverted;
        try c.Put{value: putAmount}(putUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // observe after Put and before Collect
        uint midEth = address(c).balance;
        (, uint midRecorded) = c.Acc(address(this));

        // attempt Collect
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // observe after Collect
        uint afterEth = address(c).balance;
        (, uint afterRecorded) = c.Acc(address(this));

        // If Collect succeeded then it must not have increased the contract's Ether balance
        // nor increased the recorded balance for this caller (both should be <= before Collect values).
        // If Collect reverted, no constraint.
        assert(collectReverted || (afterEth <= midEth && afterRecorded <= midRecorded));
    }

    // Allow receiving Ether when Collect sends funds out
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run tests: first optionally Put some value, then try Collect; check balances/Acc mapping reflect successful calls.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // ensure we have Ether to forward when calling Put
        require(address(this).balance >= putAmount);

        // Read before values
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Put: capture revert/success
        bool putReverted;
        try c.Put{value: putAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after Put (even if reverted, state unchanged)
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Invariant for Put: if Put did not revert then contract balance increases by putAmount
        // and Acc balance increases by putAmount, and unlockTime is set to max(unlockTime, block.timestamp).
        // Note: block.timestamp may change between calls in general, but here single transaction so same.
        bool putObservedOk = true;
        if (!putReverted) {
            // balance increases equal
            if (!(afterContractBal == beforeContractBal + putAmount)) putObservedOk = false;
            if (!(afterAccBal == beforeAccBal + putAmount)) putObservedOk = false;
            // unlockTime must be >= beforeUnlock and >= block.timestamp and equal to either provided unlockTime or block.timestamp
            if (!(afterUnlock >= beforeUnlock)) putObservedOk = false;
            if (!(afterUnlock >= block.timestamp)) putObservedOk = false;
            if (!((afterUnlock == unlockTime && unlockTime > block.timestamp) || (afterUnlock == block.timestamp && unlockTime <= block.timestamp))) putObservedOk = false;
        } else {
            // if reverted then nothing changed
            if (!(afterContractBal == beforeContractBal)) putObservedOk = false;
            if (!(afterAccBal == beforeAccBal)) putObservedOk = false;
            if (!(afterUnlock == beforeUnlock)) putObservedOk = false;
        }

        // Now attempt Collect of collectAmount (may be zero). Must have enough gas/eth; Collect is nonReentrant but previous calls finished.
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after collect
        (uint finalUnlock, uint finalAccBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // General rule: if Collect succeeded then the contract paid out collectAmount and acc.balance decreased by collectAmount
        // If Collect reverted then balances unchanged by Collect
        bool collectObservedOk = true;
        if (!collectReverted) {
            if (!(finalContractBal + collectAmount == afterContractBal)) collectObservedOk = false;
            if (!(afterAccBal >= collectAmount && finalAccBal + collectAmount == afterAccBal)) collectObservedOk = false;
        } else {
            if (!(finalContractBal == afterContractBal)) collectObservedOk = false;
            if (!(finalAccBal == afterAccBal)) collectObservedOk = false;
        }

        assert(putObservedOk && collectObservedOk);
    }

    // allow receiving Ether for forwarding Put
    receive() external payable {}
}
